import React, { Suspense, lazy } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Toaster } from 'react-hot-toast';
import { ThemeProvider } from './context/ThemeContext';
import { AuthProvider } from './context/AuthContext';
import LoadingSpinner from './components/feedback/LoadingSpinner';
import ErrorBoundary from './components/feedback/ErrorBoundary';

// Lazy loaded pages
const LoginPage = lazy(() => import('./pages/auth/LoginPage'));
const AdminDashboard = lazy(() => import('./pages/admin/Dashboard'));
const SalesRepDashboard = lazy(() => import('./pages/salesrep/Dashboard'));
const DispatchDashboard = lazy(() => import('./pages/dispatch/Dashboard'));
const CustomerOrderPage = lazy(() => import('./pages/customer/OrderPage'));
const DispatchRegisterPage = lazy(() => import('./pages/dispatch/RegisterPage'));

const queryClient = new QueryClient({
    defaultOptions: {
        queries: {
            retry: 2,
            staleTime: 5 * 60 * 1000,
            refetchOnWindowFocus: false,
        },
    },
});

function App() {
    return (
        <ErrorBoundary>
            <QueryClientProvider client={queryClient}>
                <ThemeProvider>
                    <AuthProvider>
                        <Router>
                            <Suspense fallback={<LoadingSpinner fullScreen text="Loading application..." />}>
                                <Routes>
                                    {/* Public Routes */}
                                    <Route path="/login" element={<LoginPage />} />
                                    <Route path="/order/:productId" element={<CustomerOrderPage />} />
                                    <Route path="/dispatch/register" element={<DispatchRegisterPage />} />

                                    {/* Root redirect to login if not authenticated */}
                                    <Route path="/" element={<Navigate to="/login" replace />} />

                                    {/* Admin Routes */}
                                    <Route path="/admin/*" element={<AdminDashboard />} />

                                    {/* Sales Rep Routes */}
                                    <Route path="/sales-rep/*" element={<SalesRepDashboard />} />

                                    {/* Dispatch Partner Routes */}
                                    <Route path="/dispatch/*" element={<DispatchDashboard />} />

                                    {/* Catch all - redirect to login */}
                                    <Route path="*" element={<Navigate to="/login" replace />} />
                                </Routes>
                            </Suspense>
                        </Router>
                        <Toaster
                            position="top-right"
                            toastOptions={{
                                duration: 4000,
                                style: {
                                    background: 'var(--toast-bg)',
                                    color: 'var(--toast-color)',
                                },
                            }}
                        />
                    </AuthProvider>
                </ThemeProvider>
            </QueryClientProvider>
        </ErrorBoundary>
    );
}

export default App;
